from pathlib import Path
import json, hashlib, re, sys
from datetime import datetime, timezone
sys.stdout.reconfigure(encoding='utf-8')
ROOT=Path.cwd()
R=Path('.trellis/tasks/09-28-architecture-contract-gates/research')
P=Path('.trellis/tasks/09-28-cli-tauri-architecture')
review=json.loads((R/'continuation-evidence-check.json').read_text(encoding='utf-8'))
old={Path(v['path']).name:json.loads(v['raw_utf8_text']) for v in review['pre_generation_artifacts'] if v['path'].endswith('.json')}
m=json.loads((R/'requirements-evidence.json').read_text(encoding='utf-8'))
l=json.loads((P/'research/p1-evidence-ledger.json').read_text(encoding='utf-8'))
v=json.loads((R/'evidence-mapping-validation.json').read_text(encoding='utf-8'))
errors=[]; checked_artifacts={}; results={}
def check(ok,message):
 if not ok: errors.append(message)
def digest(path):
 p=Path(path)
 return hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None
def verify_artifact(obj,label):
 p=obj['path']; actual=digest(p)
 check(actual==obj['sha256'],label+' SHA mismatch: '+p)
 if 'bytes' in obj and Path(p).is_file(): check(Path(p).stat().st_size==obj['bytes'],label+' size mismatch: '+p)
 checked_artifacts[p]=actual
check(len(m['requirements'])==39,'39 AC expected')
check(len({r['id'] for r in m['requirements']})==39,'unique AC IDs expected')
check(len(m['test_groups'])==42,'42 test groups expected after adding both native platform evidence groups')
check(len(l['findings'])==9,'9 P1 findings expected')
check(m['fix_commit'] is None,'matrix fix_commit must be null')
expected_new={'codex_settings_persistence','lint_main_tests','lint_state_tests','lint_claude_test','lint_codex_profile_test','settings_visible_i18n','doctor_deadline','tauri_process_gateway','oauth_windows_pending_failure'}
check(set(m['test_groups'])-set(old['requirements-evidence.json']['test_groups'])==expected_new,'nine new groups differ')
check(set(old['requirements-evidence.json']['test_groups'])<=set(m['test_groups']),'old group lost')
old_logs={}; source_history=0
for name,g in m['test_groups'].items():
 verify_artifact(g['test_source'],'current test source')
 check(g['source_capture_role']=='current_selector_index_only',name+' source capture role wrong')
 src=Path(g['test_source']['path']).read_text(encoding='utf-8').splitlines()
 for c in g['cases']:check(0<c['line']<=len(src) and c['selector'] in src[c['line']-1],name+' selector/line mismatch: '+c['selector'])
 before=old['requirements-evidence.json']['test_groups'].get(name)
 if before:
  if before['test_source']!=g['test_source']:
   check(before['test_source'] in g['prior_source_captures'],name+' previous test source capture lost'); source_history+=1
  after_by_path={e['path']:e for e in g['evidence']}
  for a in before['evidence']:
   if a['path'].endswith('.log'):
    old_logs[a['path']]=a['sha256']
    check(a['path'] in after_by_path and after_by_path[a['path']]['sha256']==a['sha256'],name+' previous raw log hash not preserved')
 for a in g['evidence']:
  verify_artifact(a,'test evidence')
  bind=a['source_binding']
  if 'recorded_source_sha256' in bind:
   h=bind['recorded_source_sha256']; expected=(h==g['test_source']['sha256']) if h else None
   check(bind['current_capture_matches_recorded']==expected,name+' source match annotation wrong')
  else:check(bind['status']=='not_established_by_hash_refresh',name+' historical log was promoted')
for p,h in old_logs.items():check(digest(p)==h,'historical raw log file changed: '+p)
base_refs={}
old_findings={f['finding']:f for f in old['p1-evidence-ledger.json']['findings']}
for f in l['findings']:
 check(f['fix_commit'] is None,f['finding']+' fix_commit must be null')
 check(f['final_mapping_status']=='reviewed_scoped_behavior_mapping_root_gate_reported_separately',f['finding']+' mapping acceptance wrong')
 before=old_findings[f['finding']]
 after_b={a['path']:a['sha256'] for a in f['baseline_evidence']['artifacts']}
 for a in before['baseline_evidence']['artifacts']:
  base_refs[a['path']]=a['sha256'];check(after_b.get(a['path'])==a['sha256'],f['finding']+' baseline reference changed')
 for a in f['baseline_evidence']['artifacts']:verify_artifact(a,'P1 baseline')
 for a in f['source_fingerprints']:verify_artifact(a,'P1 current source')
 for a in before['source_fingerprints']:
  check(a in f['source_fingerprints'] or a in f['prior_source_captures'],f['finding']+' previous source capture lost')
 for g in f['final_behavior_test_mapping']:
  mg=m['test_groups'][g['group']]
  for lk,mk in [('source','test_source'),('source_capture_role','source_capture_role'),('prior_source_captures','prior_source_captures'),('cases','cases'),('evidence','evidence'),('evidence_level','level'),('limits','limits')]:check(g[lk]==mg[mk],f['finding']+' group mismatch: '+g['group']+'/'+lk)
for p,h in base_refs.items():check(digest(p)==h,'baseline file changed: '+p)
rows={r['id']:r for r in m['requirements']}
old_rows={r['id']:r for r in old['requirements-evidence.json']['requirements']}
md=(R/'requirements-evidence.md').read_text(encoding='utf-8')
for rid,r in rows.items():
 check(r['requirement']==old_rows[rid]['requirement'],rid+' requirement changed')
 check('| '+rid+' | ' in md,rid+' Markdown row missing')
 for g in r['test_groups']:check(g in m['test_groups'],rid+' unknown group')
 for a in r['artifact_evidence']:verify_artifact(a,'AC artifact')
check('codex_settings_persistence' in rows['T08.AC1']['test_groups'],'real persistence helper absent from T08.AC1')
check(rows['T06.AC3']['required_platform_matrix']['macOS']=='required_not_run','macOS required boundary lost')
for rid in ['T08.AC1','T08.AC3']:check(rows[rid]['native_webview_csp_acceptance']=='not_verified',rid+' native boundary lost')
a09=next(f for f in l['findings'] if f['finding']=='A09')
check(any('macOS' in s and 'required_not_run' in s for s in a09['remaining_required_acceptance']),'P1 macOS required boundary lost')
for f in l['findings']:
 if f['finding'] in ['A14','A15']:check(f['native_webview_csp_acceptance']=='not_verified',f['finding']+' native boundary lost')
for name,run in m['continuation_runs'].items():
 verify_artifact(run,'run log')
 ex=run['execution'];verify_artifact(ex['metadata'],'run metadata')
 if 'frozen_source_evidence' in ex:verify_artifact(ex['frozen_source_evidence']['manifest'],'run freeze')
 if name in ('linux_oauth_zero_match','windows_oauth_zero_match'):
  check(run['acceptance_role']=='not_behavior_evidence_zero_matching_tests' and run['accepted_as_behavior_evidence'] is False,name+' zero-match boundary wrong')
 else:check(run['acceptance_role']=='recorded_scope_only_no_full_gate_inference',name+' acceptance role wrong')
